#!/usr/bin/env bash
# Render a Terragrunt unit into a plain Terraform root module, then plan it.
#
# Output (under <out-root>/<unit-path>/, default out-root = <repo>/rendered):
#   main.tf, variables.tf, outputs.tf   product files (module source rewritten)
#   modules/                            child modules (module-based repos only)
#   backend.tf, provider.tf             generated by Terragrunt "generate" blocks
#   terraform.tfvars                    resolved Terragrunt "inputs"
#   terragrunt-render.json              raw output of `terragrunt render --json`
#   rendered-tf.zip                     HCL-only archive (for the archive scanner)
#   tfplan, plan.json                   terraform plan and its JSON form
#
# Usage: scripts/render_and_plan.sh <unit-dir> [out-root]

set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
UNIT_ARG="${1:?usage: render_and_plan.sh <unit-dir> [out-root]}"
UNIT="$(cd "$UNIT_ARG" && pwd)"
REL="${UNIT#"$REPO_ROOT"/}"
OUT="${2:-$REPO_ROOT/rendered}/$REL"

export TG_NON_INTERACTIVE=true

rm -rf "$OUT"
mkdir -p "$OUT"
RENDER="$OUT/terragrunt-render.json"

# 1. Terragrunt resolves includes, locals, inputs and generate blocks.
(cd "$UNIT" && terragrunt render --json 2>/dev/null) > "$RENDER"
jq -e '.inputs' "$RENDER" >/dev/null || { echo "terragrunt render produced no JSON" >&2; exit 2; }

# 2. Product source: "<repo>//products/web-tier" -> "products/web-tier".
SRC="$(jq -r '.terraform.source' "$RENDER")"
SRC="${SRC#"$REPO_ROOT"}"
SRC="${SRC#//}"

# 3. Copy product files and child modules into the rendered root.
cp "$REPO_ROOT/$SRC"/*.tf "$OUT"/
if [[ -d "$REPO_ROOT/modules" ]]; then
  cp -R "$REPO_ROOT/modules" "$OUT/modules"
  for f in "$OUT"/*.tf; do
    sed 's#\.\./\.\./modules/#./modules/#g' "$f" > "$f.tmp" && mv "$f.tmp" "$f"
  done
fi

# 4. Write Terragrunt-generated files (backend, provider).
for key in $(jq -r '.generate | keys[]' "$RENDER"); do
  path="$(jq -r --arg k "$key" '.generate[$k].path' "$RENDER")"
  jq -r --arg k "$key" '.generate[$k].contents' "$RENDER" > "$OUT/$path"
done

# 5. Resolved inputs as terraform.tfvars (HCL). Values are JSON-encoded,
#    which is valid HCL for strings, numbers, booleans, lists and maps.
jq -r '.inputs | to_entries[] | "\(.key) = \(.value | tojson)"' "$RENDER" > "$OUT/terraform.tfvars"

# 6. HCL-only archive of the rendered root module (what the archive scanner receives).
(cd "$OUT" && zip -q -r rendered-tf.zip . -i '*.tf' 'terraform.tfvars')

# 7. Terraform plan on the rendered root module.
terraform -chdir="$OUT" init -input=false -no-color >/dev/null
terraform -chdir="$OUT" plan -input=false -lock=false -no-color -out=tfplan
terraform -chdir="$OUT" show -json tfplan > "$OUT/plan.json"

echo "Rendered root module: $OUT"
echo "  plan.json:        $(wc -c < "$OUT/plan.json") bytes"
echo "  rendered-tf.zip:  $(wc -c < "$OUT/rendered-tf.zip") bytes"
